import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.CdvW4CUT.js";const k=JSON.parse('{"title":"The administrator policy","description":"","frontmatter":{},"headers":[],"relativePath":"admin-policy.md","filePath":"admin-policy.md"}'),n={name:"admin-policy.md"};function l(o,s,d,h,r,p){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="the-administrator-policy" tabindex="-1">The administrator policy <a class="header-anchor" href="#the-administrator-policy" aria-label="Permalink to &quot;The administrator policy&quot;">​</a></h1><p>An administrator can limit what ripeat is allowed to do on a machine. The rules live in one file that ordinary users cannot change, and ripeat applies them to every install and upgrade. This is separate from <code>ripeat policy</code>, which creates users and groups (<a href="./policy">Users and groups</a>); this page is about restricting ripeat itself.</p><h2 id="where-the-file-is" tabindex="-1">Where the file is <a class="header-anchor" href="#where-the-file-is" aria-label="Permalink to &quot;Where the file is&quot;">​</a></h2><table tabindex="0"><thead><tr><th>OS</th><th>Path</th></tr></thead><tbody><tr><td>Linux</td><td><code>/etc/ripeat/policy.yaml</code></td></tr><tr><td>macOS</td><td><code>/Library/Application Support/ripeat/policy.yaml</code></td></tr><tr><td>Windows</td><td><code>%ProgramData%\\ripeat\\policy.yaml</code></td></tr></tbody></table><p>No file means no restrictions. The path is fixed: <code>$RIPEAT_HOME</code>, flags and environment variables cannot move it, so a user cannot point ripeat at a different rulebook.</p><h2 id="the-rules" tabindex="-1">The rules <a class="header-anchor" href="#the-rules" aria-label="Permalink to &quot;The rules&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # required, must be 1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allow_methods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">apt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">brew</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># if set, ONLY these install methods</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deny_methods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deb_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># these install methods, never</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allow_domains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">github.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># if set, downloads only from these hosts</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">require_checksums</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # refuse downloads that are not SHA-256 verified</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">user_scope_only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # refuse anything that needs admin rights</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allow_tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># if set, ONLY these tools can be installed</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deny_tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># these tools, never</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deny_accounts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # no user, group or admin-right changes (ripeat policy)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deny_mcp_run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # an AI assistant may never run installs through ripeat mcp --allow-run</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deny_taps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # no recipe packs (ripeat tap)</span></span></code></pre></div><p>Every key is optional except <code>version</code>. Unknown keys and unknown install method names are errors, so a typo cannot silently weaken a rule.</p><table tabindex="0"><thead><tr><th>Rule</th><th>What it blocks</th></tr></thead><tbody><tr><td><code>allow_methods</code>, <code>deny_methods</code></td><td>install options by method (<a href="./recipes">Recipes</a>). Deny wins over allow</td></tr><tr><td><code>allow_domains</code></td><td><code>url</code> and <code>deb_url</code> downloads whose host is not listed. <code>*.example.com</code> matches subdomains only, not <code>example.com</code> itself or a look-alike such as <code>evilexample.com</code>. <code>github_release</code> counts as <code>github.com</code>. Package managers are not affected. Hosts a download is redirected to are not checked</td></tr><tr><td><code>require_checksums</code></td><td><code>deb_url</code>, whose download cannot be checked. (<code>url</code> already requires a SHA-256 and <code>github_release</code> refuses to install without one)</td></tr><tr><td><code>user_scope_only</code></td><td>any option that needs admin rights (<a href="./privileges">Admin rights</a>)</td></tr><tr><td><code>allow_tools</code>, <code>deny_tools</code></td><td>tools by recipe name, including tools pulled in as dependencies</td></tr><tr><td><code>deny_accounts</code></td><td><code>ripeat policy</code>, even as a dry run</td></tr><tr><td><code>deny_mcp_run</code></td><td>the run tools of <code>ripeat mcp --allow-run</code> (<a href="./mcp">ripeat as an MCP server</a>): the server starts without them, and they refuse if called</td></tr><tr><td><code>deny_taps</code></td><td><code>ripeat tap add</code> and <code>update</code>; recipes from taps already added are not loaded (<a href="./taps">Recipe packs (taps)</a>)</td></tr></tbody></table><p>To stop arbitrary commands, put <code>shell</code> in <code>deny_methods</code>.</p><h2 id="how-it-is-applied" tabindex="-1">How it is applied <a class="header-anchor" href="#how-it-is-applied" aria-label="Permalink to &quot;How it is applied&quot;">​</a></h2><ul><li><strong>Every plan.</strong> Rules filter a recipe&#39;s install options. If a recipe lists <code>apt</code> then <code>scoop</code> and the policy denies <code>apt</code>, ripeat uses <code>scoop</code>. If every option is blocked, the plan stops before anything changes and says what blocked each one: <code>git is blocked by the administrator policy: apt: method &quot;apt&quot; is denied (see </code>ripeat rules<code>)</code>.</li><li><strong>Installs, upgrades and resume.</strong> An upgrade whose tool is now blocked is skipped with a note.</li><li><strong>Removing is never blocked.</strong> <code>uninstall</code> and <code>rollback</code> always work, so tightening the rules can never trap anyone with software they cannot remove.</li><li><strong>It fails closed.</strong> If the file exists but cannot be used (see below), ripeat refuses to install, upgrade or change accounts, and changes nothing. It never ignores a broken policy.</li></ul><h2 id="who-is-allowed-to-write-it" tabindex="-1">Who is allowed to write it <a class="header-anchor" href="#who-is-allowed-to-write-it" aria-label="Permalink to &quot;Who is allowed to write it&quot;">​</a></h2><p>On Linux and macOS ripeat only uses the file if it is <strong>owned by root and not writable by group or others</strong>. Otherwise a user who could edit it could lift their own limits, so ripeat refuses with a message such as <code>must be owned by root</code> or <code>must not be writable by group or others</code>. Create it as an administrator:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ripeat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ripeat/policy.yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF2&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">version: 1</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deny_methods: [shell]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root:root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ripeat/policy.yaml</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ripeat/policy.yaml</span></span></code></pre></div><p>On Windows ripeat does <strong>not</strong> check the file&#39;s permissions yet. Keep <code>%ProgramData%\\ripeat</code> writable by administrators only.</p><h2 id="seeing-and-checking-it" tabindex="-1">Seeing and checking it <a class="header-anchor" href="#seeing-and-checking-it" aria-label="Permalink to &quot;Seeing and checking it&quot;">​</a></h2><ul><li><code>ripeat rules</code> prints the policy in force in plain words, or says there is none. If the file cannot be used it says why.</li><li><code>ripeat validate</code> checks the system policy (including who owns it) along with your other files, and <code>ripeat validate &lt;file&gt;</code> checks any policy file before you install it.</li><li><code>ripeat schema admin-policy</code> prints a JSON schema for editors.</li></ul><h2 id="risk-and-the-policy" tabindex="-1">Risk and the policy <a class="header-anchor" href="#risk-and-the-policy" aria-label="Permalink to &quot;Risk and the policy&quot;">​</a></h2><p><code>ripeat assess</code> (<a href="./assess">Risk and <code>assess</code></a>) reports a tool the policy forbids as BLOCKED, and <code>--accept-risk</code> never overrides the policy.</p><h2 id="what-it-covers-besides-installs" tabindex="-1">What it covers besides installs <a class="header-anchor" href="#what-it-covers-besides-installs" aria-label="Permalink to &quot;What it covers besides installs&quot;">​</a></h2><p><code>ripeat find</code> and <code>ripeat add</code> (<a href="./find-and-add">Install by name</a>) hide or refuse candidates the policy forbids, so a user is never offered, or able to save, a recipe that could not be installed.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>It restricts ripeat, not the machine: a user can still run <code>apt</code> themselves.</li><li>A <code>shell</code> recipe can do anything, so <code>deny_methods: [shell]</code> is the only reliable guard against it.</li><li>Domain checks look at the address a recipe names, not where the download is redirected to.</li><li>Root can change the file; that is the point.</li></ul>`,24)])])}const y=i(n,[["render",l]]);export{k as __pageData,y as default};
